SELECT COUNT(*)
FROM transactions t
JOIN merchants m ON m.merchant_id = t.merchant_id
WHERE t.wallet_id = #{walletId}
  AND t.type = 'PAYMENT'
  AND t.status = 'COMPLETED'
  AND t.completed_at >= #{since}
  AND m.category_code IN

    #{category}

  AND MOD(t.amount, #{amountUnit}) = 0

